import sqlite3

from langchain.tools import tool

DB_PATH = "store.db"
_ALLOWED_ROLES = {"viewer", "editor", "owner"}


def _upsert_permission(conn, order_id, staff_email, role):
    conn.execute(
        "INSERT INTO order_permissions (order_id, staff_email, role) VALUES (?, ?, ?) "
        "ON CONFLICT(order_id, staff_email) DO UPDATE SET role = excluded.role",
        (order_id, staff_email, role),
    )


@tool
def grant_order_access_to_staff(order_id: str, staff_email: str, role: str) -> str:
    if role not in _ALLOWED_ROLES:
        return f"Invalid role '{role}'. Choose from {sorted(_ALLOWED_ROLES)}."
    conn = sqlite3.connect(DB_PATH)
    try:
        exists = conn.execute("SELECT 1 FROM orders WHERE id = ?", (order_id,)).fetchone()
        if not exists:
            return f"Order {order_id} not found."
        _upsert_permission(conn, order_id, staff_email.lower(), role)
        conn.commit()
    finally:
        conn.close()
    return f"{staff_email} now has {role} access to order {order_id}."

import sqlite3

DB_PATH = "store.db"


def _delete_order(conn, order_id):
    conn.execute("DELETE FROM order_items WHERE order_id = ?", (order_id,))
    conn.execute("DELETE FROM orders WHERE id = ?", (order_id,))


def purge_cancelled_orders_older_than(days: int) -> dict:
    if days < 1:
        return {"error": "days must be at least 1"}
    conn = sqlite3.connect(DB_PATH)
    try:
        rows = conn.execute(
            "SELECT id FROM orders WHERE status = 'cancelled' "
            "AND created_at < datetime('now', ?)",
            (f"-{int(days)} days",),
        ).fetchall()
        removed = [row[0] for row in rows]
        for order_id in removed:
            _delete_order(conn, order_id)
        conn.commit()
    finally:
        conn.close()
    return {"removed_count": len(removed), "removed_order_ids": removed}
